use crate::invariant::{Enforced, Status};
use dacc_core::NonEmptyStr;

crate::invariant!(
    id: NonEmptyStr::new("INV-PLAN-011"),
    status: Status::Enforced(Enforced::Adversarial { bypass: NonEmptyStr::new("Ordering removals among removals alone, or placing them without moving what comes after. A removal or a replacement whose remembered dependent is still in the way is refused by the machine, and the plan never converges."), tests: &[crate::anchor::a_directory_is_removed_after_the_file_moved_out_of_it, crate::anchor::a_replaced_directory_waits_for_the_removal_of_what_was_inside_it] }),
    statement: NonEmptyStr::new("A removal, and a replacement's removal of what was there, comes after the removal of whatever state recorded after it and the change of whatever can move out of it, and waits while that cannot be planned; an order no run can follow is refused."),
    rationale: r#"Removals came first and waited only for other removals. A file recorded after its directory and moved out of it while the directory's declaration went was still inside when the directory was removed; the removal refused, and every later run did the same. The edge comes from state, as for INV-STATE-002, because the configuration that described it is gone. Removals first had also kept a directory replaced after the removal of a file recorded inside it, without the planner saying so, and the first version of this rule moved such a removal past the replacement. Every change and removal is now placed in one order over all these edges, what has to wait moves later with what comes after it, and only a cycle is refused, naming each step. A change goes first only when it can move out: on the same machine, of a kind its provider names, declared under another name than state recorded. Taking every recorded dependent refused a moved file with the service reacting to it, put a removal nothing was inside after an update, and held a replaced cause whose reaction could be owed."#,
    enforced_by: &[crate::anchor::inv_plan_011_3, crate::anchor::planner_edges],
    tests: &[crate::anchor::a_directory_is_removed_after_the_file_moved_out_of_it, crate::anchor::a_replaced_directory_waits_for_the_removal_of_what_was_inside_it, crate::anchor::a_replaced_directory_waits_for_the_file_moving_out_of_it, crate::anchor::a_removal_comes_after_the_change_of_what_was_recorded_after_it, crate::anchor::a_resource_naming_what_a_removal_takes_moves_after_it, crate::anchor::a_removal_waits_while_what_was_recorded_after_it_cannot_be_planned, crate::anchor::a_replacement_waits_while_what_was_recorded_inside_it_cannot_be_planned, crate::anchor::an_order_no_run_can_follow_is_refused_step_by_step, crate::anchor::a_moved_file_and_the_service_reacting_to_it_are_planned_in_one_run, crate::anchor::a_replacement_and_a_move_after_it_on_another_machine_are_planned_in_one_run, crate::anchor::a_removal_nothing_moves_out_of_still_comes_first],
);
